floor_fn:
"""Given the string blob of data from `tmux capture-pane`, returns an array of line strings.

	Arguments:
		data -- String blob of data from `tmux capture-pane`
		nlines -- Maximum number of lines to return

	Returns:
		An array of line strings.  Each line string corresponds to a single visible line such that
		a wrapped line is returned as multiple visible lines.  Nonprintable characters are removed
		and tabs are converted to spaces.
	"""
def process_pane_capture_lines(data: Any, nlines: Any = None) -> object {
    lines = [
        ''.join(
            ['        ' if (c == '\t') else c if c.isprintable() else '' for c in line]
        ) for line in data.split('\n')
    ];
    if (nlines != None) {
        lines = lines[:nlines];
    }
    return lines;
}

test_blocks:
test "t0" {
    assert (
        process_pane_capture_lines(
            'line 1\nline 2\nline 3\nline 4\nline 5\nline 6\nline 7\nline 8\nline 9\nline 10'
        )
        == [
            'line 1',
            'line 2',
            'line 3',
            'line 4',
            'line 5',
            'line 6',
            'line 7',
            'line 8',
            'line 9',
            'line 10'
        ]
    );;
}

test "t1" {
    assert (
        process_pane_capture_lines('The quick brown fox jumps over the lazy dog', 1)
        == ['The quick brown fox jumps over the lazy dog']
    );;
}

test "t2" {
    assert (process_pane_capture_lines('''\
abc
def
ghi''') == ['abc', 'def', 'ghi']);;
}

test "t3" {
    assert (
        process_pane_capture_lines('The quick brown fox jumps over the lazy dog')
        == ['The quick brown fox jumps over the lazy dog']
    );;
}

test "t4" {
    assert (process_pane_capture_lines("""
	Line 1
	Line 2
	Line 3
	""", 0) == []);;
}

test "t5" {
    assert (
        process_pane_capture_lines('line 1\n\033[0mline 2\n\033[0m', 1) == ['line 1']
    );;
}

test "t6" {
    assert (process_pane_capture_lines('''\
a

b''') == ['a', '', 'b']);;
}

test "t7" {
    assert (process_pane_capture_lines("""
	test line 1
	test line 2
	""", 0) == []);;
}

test "t8" {
    assert (
        process_pane_capture_lines(
            'The quick brown fox jumps over the lazy dog\n1\n2\n3\n4\n5\n6\n7\n8\n9\n0',
            3
        )
        == ['The quick brown fox jumps over the lazy dog', '1', '2']
    );;
}

test "t9" {
    assert (process_pane_capture_lines('foo\nbar\nbaz\n', 3) == ['foo', 'bar', 'baz']);;
}

test "t10" {
    assert (
        process_pane_capture_lines(
            'The quick brown fox jumps over the lazy dog\n1\n2\n3\n4\n5\n6\n7\n8\n9\n0',
            6
        )
        == ['The quick brown fox jumps over the lazy dog', '1', '2', '3', '4', '5']
    );;
}

test "t11" {
    assert (
        process_pane_capture_lines(
            'The quick brown fox jumps over the lazy dog\n1\n2\n3\n4\n5\n6\n7\n8\n9\n0',
            11
        )
        == [
            'The quick brown fox jumps over the lazy dog',
            '1',
            '2',
            '3',
            '4',
            '5',
            '6',
            '7',
            '8',
            '9',
            '0'
        ]
    );;
}

test "t12" {
    assert (
        process_pane_capture_lines('foo\nbar\nbaz\n', 4) == ['foo', 'bar', 'baz', '']
    );;
}

test "t13" {
    assert (process_pane_capture_lines('''\
a
b
c
d''') == ['a', 'b', 'c', 'd']);;
}
